-- State transitions declared for MailingTrace: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION mailing.mailing_traces_trace_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."trace_status" IS DISTINCT FROM OLD."trace_status" AND NOT (
           (COALESCE(OLD."trace_status"::text, ''), COALESCE(NEW."trace_status"::text, '')) IN (('open', 'bounce'), ('open', 'reply'), ('outgoing', 'bounce'), ('outgoing', 'cancel'), ('outgoing', 'error'), ('outgoing', 'open'), ('outgoing', 'pending'), ('outgoing', 'process'), ('outgoing', 'reply'), ('outgoing', 'sent'), ('pending', 'bounce'), ('pending', 'error'), ('pending', 'open'), ('pending', 'reply'), ('pending', 'sent'), ('process', 'bounce'), ('process', 'error'), ('process', 'open'), ('process', 'pending'), ('process', 'reply'), ('process', 'sent'), ('sent', 'bounce'), ('sent', 'error'), ('sent', 'open'), ('sent', 'reply'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: mailing_traces.trace_status % -> %', OLD."trace_status", NEW."trace_status"
            USING ERRCODE = 'check_violation', COLUMN = 'trace_status', CONSTRAINT = 'tg_mailing_traces__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS mailing_traces_trace_status_transition_check ON mailing.mailing_traces;
CREATE TRIGGER mailing_traces_trace_status_transition_check
    BEFORE UPDATE OF "trace_status" ON mailing.mailing_traces
    FOR EACH ROW EXECUTE FUNCTION mailing.mailing_traces_trace_status_transition_check();
